from AlgorithmImports import *

class QuantConnectAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.strategy_a_sma = self.SMA(self.symbols["SPY"], 20, Resolution.Daily)
        self.prev_spy_close = None
        self.prev_spy_sma = None

        self.strategy_b_rsi = self.RSI(self.symbols["AAPL"], 14, Resolution.Daily)
        self.prev_aapl_close = None
        self.strategy_b_red_days = 0

    def OnData(self, data):
        for ticker in self.tickers:
            if self.symbols[ticker] not in data:
                return

        if not self.strategy_a_sma.IsReady or not self.strategy_b_rsi.IsReady:
            return

        spy_close = data[self.symbols["SPY"]].Close
        spy_sma = self.strategy_a_sma.Current.Value
        aapl_close = data[self.symbols["AAPL"]].Close
        aapl_rsi = self.strategy_b_rsi.Current.Value

        spy_shares = self.Portfolio[self.symbols["SPY"]].Quantity
        aapl_shares = self.Portfolio[self.symbols["AAPL"]].Quantity

        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.strategy_b_red_days += 1
            else:
                self.strategy_b_red_days = 0

        if spy_shares > 0:
            if self.prev_spy_close is not None and self.prev_spy_close > self.prev_spy_sma and spy_close <= spy_sma:
                self.MarketOrder(self.symbols["SPY"], -spy_shares)

        if spy_shares == 0:
            if self.prev_spy_close is not None and self.prev_spy_close <= self.prev_spy_sma and spy_close > spy_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                buy_value = portfolio_value * 0.4
                shares_to_buy = int(buy_value / spy_close)
                if shares_to_buy > 0:
                    self.MarketOrder(self.symbols["SPY"], shares_to_buy)

        if aapl_shares > 0:
            if aapl_rsi > 60:
                self.MarketOrder(self.symbols["AAPL"], -aapl_shares)

        if aapl_shares == 0:
            if self.strategy_b_red_days >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.MarketOrder(self.symbols["AAPL"], shares_to_buy)

        self.prev_spy_close = spy_close
        self.prev_spy_sma = spy_sma
        self.prev_aapl_close = aapl_close

