from AlgorithmImport import *

class QuantConnectAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol

        self.spy_symbol = self.symbols["SPY"]
        self.aapl_symbol = self.symbols["AAPL"]

        self.spy_lot = 0
        self.spy_prices = []
        self.spy_last_close = None
        self.spy_last_sma = None

        self.aapl_lot = 0
        self.aapl_prices = []
        self.aapl_last_close = None
        self.aapl_red_days = 0

        self.ready = False

    def OnData(self, data):
        for ticker in self.tickers:
            if not data.ContainsKey(self.symbols[ticker]):
                return

        spy_bar = data[self.spy_symbol]
        aapl_bar = data[self.aapl_symbol]

        self.spy_prices.append(spy_bar.Close)
        self.aapl_prices.append(aapl_bar.Close)

        if len(self.spy_prices) > 21:
            self.spy_prices.pop(0)
        if len(self.aapl_prices) > 15:
            self.aapl_prices.pop(0)

        if self.aapl_last_close is None:
            self.aapl_last_close = aapl_bar.Close
        else:
            if aapl_bar.Close < self.aapl_last_close:
                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0
            self.aapl_last_close = aapl_bar.Close

        if not self.ready:
            if len(self.spy_prices) >= 21 and len(self.aapl_prices) >= 15:
                self.ready = True
            else:
                return

        spy_sma = sum(self.spy_prices[1:21]) / 20.0
        aapl_rsi = self.calculate_rsi(self.aapl_prices)

        if self.spy_last_sma is not None:
            if self.spy_lot > 0:
                if self.spy_last_close > self.spy_last_sma and spy_bar.Close <= spy_sma:
                    self.Sell(self.spy_symbol, self.spy_lot)
                    self.spy_lot = 0
            else:
                if self.spy_last_close <= self.spy_last_sma and spy_bar.Close > spy_sma:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    buy_value = portfolio_value * 0.4
                    shares = int(buy_value / spy_bar.Close)
                    if shares > 0:
                        self.Buy(self.spy_symbol, shares)
                        self.spy_lot = shares

        if self.aapl_lot > 0:
            if aapl_rsi > 60:
                self.Sell(self.aapl_symbol, self.aapl_lot)
                self.aapl_lot = 0
        else:
            if self.aapl_red_days >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / aapl_bar.Close)
                    if shares > 0:
                        self.Buy(self.aapl_symbol, shares)
                        self.aapl_lot = shares

        self.spy_last_close = spy_bar.Close
        self.spy_last_sma = spy_sma

    def calculate_rsi(self, prices):
        if len(prices) < 2:
            return 50.0

        deltas = [prices[i] - prices[i-1] for i in range(1, len(prices))]

        if len(deltas) < 14:
            return 50.0

        gains = sum(d for d in deltas[:14] if d > 0) / 14.0
        losses = sum(-d for d in deltas[:14] if d < 0) / 14.0

        for d in deltas[14:]:
            if d > 0:
                gains = (gains * 13 + d) / 14.0
                losses = (losses * 13) / 14.0
            else:
                gains = (gains * 13) / 14.0
                losses = (losses * 13 - d) / 14.0

        if losses == 0:
            return 100.0 if gains > 0 else 50.0

        rs = gains / losses
        rsi = 100.0 - (100.0 / (1.0 + rs))
        return rsi

