    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol

        self.spy_symbol = self.symbols["SPY"]
        self.aapl_symbol = self.symbols["AAPL"]

        self.spy_holdings = 0
        self.aapl_holdings = 0

        self.spy_prices = []
        self.aapl_prices = []

        self.spy_sma_period = 20
        self.aapl_rsi_period = 14
        self.aapl_consecutive_reds = 0

    def OnData(self, data):
        for ticker in self.tickers:
            if not data.ContainsKey(self.symbols[ticker]):
                return

        spy_price = data[self.spy_symbol].Close
        aapl_price = data[self.aapl_symbol].Close

        self.spy_prices.append(spy_price)
        self.aapl_prices.append(aapl_price)

        if len(self.aapl_prices) >= 2:
            if self.aapl_prices[-1] < self.aapl_prices[-2]:
                self.aapl_consecutive_reds += 1
            else:
                self.aapl_consecutive_reds = 0

        spy_cross_ready = len(self.spy_prices) >= self.spy_sma_period + 1
        aapl_ready = len(self.aapl_prices) >= self.aapl_rsi_period + 1

        spy_sma = None
        prev_spy_sma = None
        prev_spy_price = None
        if spy_cross_ready:
            spy_sma = sum(self.spy_prices[-self.spy_sma_period:]) / self.spy_sma_period
            prev_spy_sma = sum(self.spy_prices[-self.spy_sma_period-1:-1]) / self.spy_sma_period
            prev_spy_price = self.spy_prices[-2]

        aapl_rsi = None
        if aapl_ready:
            aapl_rsi = self.calculate_rsi(self.aapl_prices, self.aapl_rsi_period)

        if spy_cross_ready and self.spy_holdings > 0:
            if prev_spy_price >= prev_spy_sma and spy_price < spy_sma:
                self.MarketOrder(self.spy_symbol, -self.spy_holdings)
                self.spy_holdings = 0

        if aapl_ready and self.aapl_holdings > 0:
            if aapl_rsi > 60:
                self.MarketOrder(self.aapl_symbol, -self.aapl_holdings)
                self.aapl_holdings = 0

        if spy_cross_ready and self.spy_holdings == 0:
            if prev_spy_price <= prev_spy_sma and spy_price > spy_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                available_cash = self.Portfolio.Cash
                invest_amount = min(portfolio_value * 0.4, available_cash)
                shares = int(invest_amount / spy_price)
                if shares > 0:
                    self.MarketOrder(self.spy_symbol, shares)
                    self.spy_holdings = shares

        if aapl_ready and self.aapl_holdings == 0:
            if self.aapl_consecutive_reds >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares = int(20000 / aapl_price)
                    self.MarketOrder(self.aapl_symbol, shares)
                    self.aapl_holdings = shares

    def calculate_rsi(self, prices, period):
        if len(prices) < period + 1:
            return None

        gains = 0
        losses = 0
        for i in range(-period, 0):
            change = prices[i] - prices[i - 1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 0

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

