from AlgorithmImports import *

class QuantConnectLeanAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        # Subscribe to equities
        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in tickers:
            self.AddEquity(ticker, Resolution.Daily)

        # Strategy A (SPY)
        self.spy_symbol = self.Symbol("SPY")
        self.spy_sma = self.SMA("SPY", 50, Resolution.Daily)
        self.spy_last_cross = None

        # Strategy B (AAPL)
        self.aapl_symbol = self.Symbol("AAPL")
        self.aapl_rsi = self.RSI("AAPL", 14, Resolution.Daily)
        self.aapl_red_days = 0
        self.aapl_last_close = None

    def OnData(self, data):
        # Check if all required data is available
        required_tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in required_tickers:
            if not data.ContainsKey(ticker):
                return

        # Get current prices
        spy_close = self.Securities["SPY"].Close
        aapl_close = self.Securities["AAPL"].Close

        # Update AAPL consecutive red days count
        if self.aapl_last_close is not None:
            if aapl_close < self.aapl_last_close:
                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0
        self.aapl_last_close = aapl_close

        # Strategy A: SPY
        if self.spy_sma.IsReady:
            spy_sma_value = self.spy_sma.Current.Value
            spy_holdings = self.Portfolio[self.spy_symbol].Quantity

            # Evaluate sell first
            if spy_holdings > 0:
                if self.spy_last_cross is not None:
                    prev_close, prev_sma = self.spy_last_cross
                    if prev_close >= prev_sma and spy_close < spy_sma_value:
                        self.Sell(self.spy_symbol, spy_holdings)

            # Evaluate buy
            if spy_holdings == 0:
                if self.spy_last_cross is not None:
                    prev_close, prev_sma = self.spy_last_cross
