                if c >= 20000:
                    qty = int(20000 / aapl_close)
                    if qty > 0:
                        self.Buy("AAPL", qty)
                        self.strategy_b_shares = qty

    def _calc_rsi(self, closes):
        if len(closes) < 14:
            return 0
        c = closes[-14:]
        g = 0.0
        l = 0.0
        for i in range(1, 14):
            d = c[i] - c[i-1]
            if d > 0:
                g += d
            else:
                l -= d
        ag = g / 14
        al = l / 14
        if al == 0:
            return 100
        rs = ag / al
        return 100 - 100 / (1 + rs)

