from AlgorithmImport import *

class QuantConnectLeanAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        self.closes = {}

        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol
            self.closes[ticker] = RollingWindow[float](50)

        self.bar_count = 0

    def OnData(self, data):
        if not all(self.symbols[ticker] in data for ticker in self.tickers):
            return

        for ticker in self.tickers:
            self.closes[ticker].Add(data[self.symbols[ticker]].Close)

        self.bar_count += 1

        if self.bar_count <= 20:
            return

        spy_close = self.closes["SPY"][0]
        spy_close_prev = self.closes["SPY"][1]
        aapl_close = self.closes["AAPL"][0]

        spy_holdings = int(self.Portfolio.Holdings[self.symbols["SPY"]].Quantity)
        aapl_holdings = int(self.Portfolio.Holdings[self.symbols["AAPL"]].Quantity)

        spy_sma_current = sum(list(self.closes["SPY"])[:20]) / 20
        spy_sma_prev = sum(list(self.closes["SPY"])[1:21]) / 20

        aapl_closes_for_rsi = list(self.closes["AAPL"])[:15]
        aapl_rsi = self.calculate_rsi(aapl_closes_for_rsi)

        aapl_red_3 = (self.closes["AAPL"][0] < self.closes["AAPL"][1] and 
                      self.closes["AAPL"][1] < self.closes["AAPL"][2] and 
                      self.closes["AAPL"][2] < self.closes["AAPL"][3])

        if spy_holdings > 0:
            if spy_close_prev >= spy_sma_prev and spy_close < spy_sma_current:
                self.Liquidate(self.symbols["SPY"])

        if aapl_holdings > 0:
            if aapl_rsi > 60:
                self.Liquidate(self.symbols["AAPL"])

        if spy_holdings == 0:
            if spy_close_prev <= spy_sma_prev and spy_close > spy_sma_current:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.4
                target_shares = int(target_value / spy_close)
                if target_shares > 0:
                    self.Buy(self.symbols["SPY"], target_shares)

        if aapl_holdings == 0:
            if aapl_red_3:
                if self.Portfolio.Cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.Buy(self.symbols["AAPL"], shares)

    def calculate_rsi(self, closes):
        if len(closes) < 15:
            return 50

        gains = 0
        losses = 0
        for i in range(14):
            change = closes[i] - closes[i+1]
            if change > 0:
                gains += change
            else:
                losses += -change

        avg_gain = gains / 14
        avg_loss = losses / 14

        if avg_loss == 0:
            return 100

        rs = avg_gain / avg_loss
