        today_close = self.spy_closes[-1]

        yesterday_ma = sum(self.spy_closes[-51:-1]) / 50
        today_ma = sum(self.spy_closes[-50:]) / 50

        return yesterday_close >= yesterday_ma and today_close < today_ma

    def check_aapl_red_3_days(self):
        if len(self.aapl_closes) < 4:
            return False

        return (self.aapl_closes[-1] < self.aapl_closes[-2] and
                self.aapl_closes[-2] < self.aapl_closes[-3] and
                self.aapl_closes[-3] < self.aapl_closes[-4])

    def check_aapl_rsi_above_60(self):
        if len(self.aapl_closes) < 15:
            return False

        rsi = self.calculate_rsi(self.aapl_closes[-15:])
        return rsi > 60

    def calculate_rsi(self, closes):
        gains = 0
        losses = 0

        for i in range(1, 15):
            change = closes[i] - closes[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / 14
        avg_loss = losses / 14

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi
