            self.spy_close_prev = spy_close
            self.spy_ma_prev = spy_ma
            self.aapl_close_prev = aapl_close
            return

        spy_qty = self.Portfolio[self.symbols["SPY"]].Quantity

        if spy_qty > 0:
            if (self.spy_close_prev >= self.spy_ma_prev) and (spy_close < spy_ma):
                self.Liquidate(self.symbols["SPY"])
                spy_qty = 0

        if spy_qty == 0:
            if (self.spy_close_prev <= self.spy_ma_prev) and (spy_close > spy_ma):
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.4
                qty = int(invest_amount / spy_close)
                if qty > 0:
                    self.MarketOrder(self.symbols["SPY"], qty)

        aapl_qty = self.Portfolio[self.symbols["AAPL"]].Quantity

        if aapl_qty > 0:
