        if aapl_qty == 0:
            if self.aapl_red_days >= 3:
                if self.Portfolio.Cash >= 20000:
                    qty = int(20000 / aapl_close)
                    if qty > 0:
                        self.MarketOrder(self.symbols["AAPL"], qty)

        self.spy_close_prev = spy_close
        self.spy_ma_prev = spy_ma
        self.aapl_close_prev = aapl_close

    def calculate_rsi(self, prices):
        if len(prices) < 2:
            return None

        gains = 0.0
        losses = 0.0

        for i in range(1, len(prices)):
            change = prices[i] - prices[i-1]
            if change > 0:
                gains += change
            else:
                losses += abs(change)

        avg_gain = gains / (len(prices) - 1)
        avg_loss = losses / (len(prices) - 1)

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 0

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

