        self.aapl_prices = []
        self.aapl_prev_close = None
        self.aapl_red_streak = 0

    def OnData(self, data):
        # Check if all subscribed symbols have data
        for symbol in self.symbols:
            if symbol not in data:
                return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        self.spy_prices.append(spy_close)
        self.aapl_prices.append(aapl_close)

        # Wait until all indicators have sufficient history
        if len(self.spy_prices) < 101 or len(self.aapl_prices) < 15:
            self.aapl_prev_close = aapl_close
            self.spy_prev_close = spy_close
            return

        spy_sma_100 = sum(self.spy_prices[-100:]) / 100
        aapl_rsi_14 = self.CalculateRSI(self.aapl_prices, 14)

        # Track AAPL red streak
        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # === STRATEGY A (SPY) ===
        # Evaluate sell first
        if self.spy_lot_size > 0:
            if self.spy_prev_close is not None and self.spy_prev_sma is not None:
                if self.spy_prev_close > self.spy_prev_sma and spy_close <= spy_sma_100:
                    self.MarketOrder("SPY", -self.spy_lot_size)
                    self.spy_lot_size = 0

        # Evaluate buy
        if self.spy_lot_size == 0:
            if self.spy_prev_close is not None and self.spy_prev_sma is not None:
                if self.spy_prev_close <= self.spy_prev_sma and spy_close > spy_sma_100:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    invest_amount = portfolio_value * 0.4
                    shares_to_buy = int(invest_amount / spy_close)
                    if shares_to_buy > 0:
