                self.spy_shares = 0

        if self.aapl_shares > 0:
            rsi = self.calculate_rsi(self.aapl_closes)
            if rsi > 60:
                self.Sell("AAPL", self.aapl_shares)
                self.aapl_shares = 0

    def evaluate_buys(self, data):
        if self.spy_shares == 0:
            sma_prev = sum(self.spy_closes[-101:-1]) / 100.0
            sma_curr = sum(self.spy_closes[-100:]) / 100.0

            if self.spy_closes[-2] <= sma_prev and self.spy_closes[-1] > sma_curr:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                investment = portfolio_value * 0.4
                shares = int(investment / self.spy_closes[-1])
                if shares > 0:
                    self.Buy("SPY", shares)
                    self.spy_shares = shares

        if self.aapl_shares == 0:
            if len(self.aapl_closes) >= 4:
