                for i in range(1, 4):
                    if self.aapl_closes[-i] < self.aapl_closes[-(i+1)]:
                        red_count += 1
                    else:
                        break

                if red_count >= 3:
                    cash = self.Portfolio.Cash
                    if cash >= 20000:
                        shares = int(20000 / self.aapl_closes[-1])
                        if shares > 0:
                            self.Buy("AAPL", shares)
                            self.aapl_shares = shares

    def calculate_rsi(self, closes):
        if len(closes) < 14:
            return 50.0

        period = closes[-14:]

        gains = 0.0
        losses = 0.0

        for i in range(1, len(period)):
            change = period[i] - period[i-1]
            if change > 0:
                gains += change
            else:
                losses += -change

        avg_gain = gains / 13.0
        avg_loss = losses / 13.0

        if avg_loss == 0:
            return 100.0

        rs = avg_gain / avg_loss
        rsi = 100.0 - (100.0 / (1.0 + rs))
        return rsi

