        self.aapl_red_streak = 0
        self.aapl_close_prev = None
        self.spy_close_prev = None
        self.spy_sma_prev = None

        self.SetWarmUp(100)

    def OnData(self, data):
        for sym_name in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            if self.symbols[sym_name] not in data:
                return

        spy_bar = data[self.symbols["SPY"]]
        aapl_bar = data[self.symbols["AAPL"]]

        if self.aapl_close_prev is not None:
            if aapl_bar.Close < self.aapl_close_prev:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
        self.aapl_close_prev = aapl_bar.Close

        if self.IsWarmingUp:
            self.spy_close_prev = spy_bar.Close
            return

        spy_history = self.History(self.symbols["SPY"], 100, Resolution.Daily)
        if len(spy_history) < 100:
            return

        spy_sma = spy_history['close'].mean()

        aapl_history = self.History(self.symbols["AAPL"], 15, Resolution.Daily)
        if len(aapl_history) < 15:
            return

        aapl_rsi = self.CalculateRSI(list(aapl_history['close']), 14)

        spy_lot = self.Portfolio[self.symbols["SPY"]].Quantity
        aapl_lot = self.Portfolio[self.symbols["AAPL"]].Quantity

        if spy_lot > 0:
            if self.spy_close_prev is not None and self.spy_sma_prev is not None:
                if self.spy_close_prev >= self.spy_sma_prev and spy_bar.Close < spy_sma:
                    self.MarketOrder(self.symbols["SPY"], -int(spy_lot))

        if spy_lot == 0:
            if self.spy_close_prev is not None and self.spy_sma_prev is not None:
                if self.spy_close_prev <= self.spy_sma_prev and spy_bar.Close > spy_sma:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    investment_amount = portfolio_value * 0.40
                    shares_to_buy = int(investment_amount / spy_bar.Close)
                    if shares_to_buy > 0:
                        self.MarketOrder(self.symbols["SPY"], shares_to_buy)

        if aapl_lot > 0:
            if aapl_rsi is not None and aapl_rsi > 60:
                self.MarketOrder(self.symbols["AAPL"], -int(aapl_lot))

        if aapl_lot == 0:
            if self.aapl_red_streak >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_bar.Close)
                    if shares_to_buy > 0:
                        self.MarketOrder(self.symbols["AAPL"], shares_to_buy)

        self.spy_close_prev = spy_bar.Close
        self.spy_sma_prev = spy_sma

    def CalculateRSI(self, closes, period):
        if len(closes) < period + 1:
            return None

        deltas = [closes[i] - closes[i-1] for i in range(1, len(closes))]
        deltas = deltas[-period:]

        gains = sum([d for d in deltas if d > 0])
        losses = sum([-d for d in deltas if d < 0])

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))

        return rsi

