    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol

        # Slot 1 - Strategy A (SPY)
        self.slot1_lot = 0
        self.slot1_sma = self.SMA(self.symbols["SPY"], 100, Resolution.Daily)
        self.slot1_prev_spy_close = None
        self.slot1_prev_sma = None

        # Slot 2 - Strategy B (AAPL)
        self.slot2_lot = 0
        self.slot2_red_days = 0
        self.slot2_prev_aapl_close = None
        self.slot2_rsi = self.RSI(self.symbols["AAPL"], 14, Resolution.Daily)

    def OnData(self, data):
        # Check if all subscribed tickers have data
        for ticker in self.tickers:
            if self.symbols[ticker] not in data:
                return

        current_prices = {}
        for ticker in self.tickers:
            current_prices[ticker] = data[self.symbols[ticker]].Close

        # Initialize on first bar
        if self.slot1_prev_spy_close is None:
            self.slot1_prev_spy_close = current_prices["SPY"]

        if self.slot2_prev_aapl_close is None:
            self.slot2_prev_aapl_close = current_prices["AAPL"]
        else:
            # Update red day counter (only after initialization)
            if current_prices["AAPL"] < self.slot2_prev_aapl_close:
                self.slot2_red_days += 1
            else:
                self.slot2_red_days = 0

        # Check if both indicators are ready
        if not (self.slot1_sma.IsReady and self.slot2_rsi.IsReady):
            self.slot1_prev_spy_close = current_prices["SPY"]
            self.slot2_prev_aapl_close = current_prices["AAPL"]
            if self.slot1_sma.IsReady:
                self.slot1_prev_sma = self.slot1_sma.Current.Value
            return

        # Both indicators ready
        current_sma = self.slot1_sma.Current.Value
        current_rsi = self.slot2_rsi.Current.Value

        # Only process trades if we have previous SMA value
        if self.slot1_prev_sma is None:
            self.slot1_prev_sma = current_sma
            self.slot1_prev_spy_close = current_prices["SPY"]
            self.slot2_prev_aapl_close = current_prices["AAPL"]
            return

        # SELLS FIRST
        # Slot 1 - Sell if SPY crosses below SMA
        if self.slot1_lot > 0:
            if self.slot1_prev_spy_close > self.slot1_prev_sma and current_prices["SPY"] <= current_sma:
                self.Liquidate(self.symbols["SPY"])
                self.slot1_lot = 0

        # Slot 2 - Sell if RSI > 60
        if self.slot2_lot > 0:
            if current_rsi > 60:
                self.Liquidate(self.symbols["AAPL"])
                self.slot2_lot = 0

        # BUYS SECOND
        # Slot 1 - Buy if SPY crosses above SMA
        if self.slot1_lot == 0:
            if self.slot1_prev_spy_close <= self.slot1_prev_sma and current_prices["SPY"] > current_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                investment_amount = portfolio_value * 0.4
                shares_to_buy = int(investment_amount / current_prices["SPY"])
                if shares_to_buy > 0:
                    self.Buy(self.symbols["SPY"], shares_to_buy)
                    self.slot1_lot = shares_to_buy

        # Slot 2 - Buy if 3 consecutive red days
        if self.slot2_lot == 0:
            if self.slot2_red_days >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / current_prices["AAPL"])
                    if shares_to_buy > 0:
                        self.Buy(self.symbols["AAPL"], shares_to_buy)
                        self.slot2_lot = shares_to_buy

        # Update previous values for next iteration
        self.slot1_prev_spy_close = current_prices["SPY"]
        self.slot1_prev_sma = current_sma
        self.slot2_prev_aapl_close = current_prices["AAPL"]

