class QuantConnectLean(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        # Subscribe to equities
        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol

        # Tracking data
        self.close_history = {ticker: deque(maxlen=100) for ticker in self.tickers}
        self.red_day_streak = {ticker: 0 for ticker in self.tickers}
        self.sma_history = deque(maxlen=2)

        # Indicators
        self.rsi = self.RSI(self.symbols["AAPL"], 14, Resolution.Daily)
        self.AddIndicator(self.symbols["AAPL"], self.rsi)

        self.spy_sma100 = self.SMA(self.symbols["SPY"], 100, Resolution.Daily)
        self.AddIndicator(self.symbols["SPY"], self.spy_sma100)

    def OnData(self, data):
        # Check if all symbols have data
        for ticker in self.tickers:
            if not data.ContainsKey(self.symbols[ticker]):
                return

        # Update price history
        for ticker in self.tickers:
            close = data[self.symbols[ticker]].Close
            self.close_history[ticker].append(close)

        # Update red day streaks
        for ticker in self.tickers:
            if len(self.close_history[ticker]) >= 2:
                closes = list(self.close_history[ticker])
                if closes[-1] < closes[-2]:
                    self.red_day_streak[ticker] += 1
                else:
                    self.red_day_streak[ticker] = 0

        # Check if indicators are ready
        if not self.spy_sma100.IsReady or not self.rsi.IsReady:
            return

        # Update SMA history
        self.sma_history.append(self.spy_sma100.Current.Value)
        if len(self.sma_history) < 2:
            return

        # Get prices and previous prices
        closes_spy = list(self.close_history["SPY"])
        closes_aapl = list(self.close_history["AAPL"])
        spy_price = closes_spy[-1]
        aapl_price = closes_aapl[-1]
        spy_prev = closes_spy[-2]

        # Get SMA values
        sma_list = list(self.sma_history)
        spy_sma = sma_list[-1]
        spy_sma_prev = sma_list[-2]

        # Get RSI
        aapl_rsi = self.rsi.Current.Value

        # Get holdings and cash
        spy_holding = int(self.Portfolio[self.symbols["SPY"]].Quantity)
        aapl_holding = int(self.Portfolio[self.symbols["AAPL"]].Quantity)
        available_cash = self.Portfolio.Cash
        portfolio_value = self.Portfolio.TotalPortfolioValue

        # Evaluate sells before buys

        if spy_holding > 0:
            if spy_prev >= spy_sma_prev and spy_price < spy_sma:
                self.Sell(self.symbols["SPY"], spy_holding)
                spy_holding = 0

        if aapl_holding > 0:
            if aapl_rsi > 60:
                self.Sell(self.symbols["AAPL"], aapl_holding)
                aapl_holding = 0

        # Evaluate buys

        if spy_holding == 0:
            if spy_prev <= spy_sma_prev and spy_price > spy_sma:
                target_value = portfolio_value * 0.4
                shares_to_buy = int(target_value / spy_price)
                if shares_to_buy > 0:
                    self.Buy(self.symbols["SPY"], shares_to_buy)
                    spy_holding = shares_to_buy
                    available_cash -= shares_to_buy * spy_price

        if aapl_holding == 0:
            if self.red_day_streak["AAPL"] >= 3:
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_price)
                    if shares_to_buy > 0:
                        self.Buy(self.symbols["AAPL"], shares_to_buy)
                        aapl_holding = shares_to_buy

