class CompleteQuantConnectAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        # Subscribe to daily resolution
        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in self.tickers:
            self.AddEquity(ticker, Resolution.Daily)

        # Price history
        self.prices = {ticker: [] for ticker in self.tickers}

        # Strategy lots
        self.strategy_a_shares = 0  # SPY
        self.strategy_b_shares = 0  # AAPL

        # Strategy state
        self.aapl_red_streak = 0

    def OnData(self, data):
        # Check if all required tickers have data
        if not all(data.ContainsKey(ticker) for ticker in self.tickers):
            return

        # Update price history
        for ticker in self.tickers:
            self.prices[ticker].append(data[ticker].Close)

        # Need 101 SPY closes for 100-day SMA calculation
        # Need 14 AAPL closes for RSI calculation
        if len(self.prices["SPY"]) < 101 or len(self.prices["AAPL"]) < 14:
            return

        # Get current prices
        spy_price = self.prices["SPY"][-1]
        aapl_price = self.prices["AAPL"][-1]

        # Calculate SPY 100-day SMA (last 100 closes, not including today)
        spy_sma_today = sum(self.prices["SPY"][-100:]) / 100
        spy_sma_yesterday = sum(self.prices["SPY"][-101:-1]) / 100

        # Calculate AAPL 14-day RSI
        aapl_rsi = self.CalculateRSI(self.prices["AAPL"], 14)

        # Update AAPL red streak
        if self.prices["AAPL"][-1] < self.prices["AAPL"][-2]:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        # Evaluate sells first
        # Strategy A sell: SPY crosses below 100-day SMA
        if self.strategy_a_shares > 0:
            if self.prices["SPY"][-2] >= spy_sma_yesterday and spy_price < spy_sma_today:
                self.MarketOrder("SPY", -self.strategy_a_shares)
                self.strategy_a_shares = 0

        # Strategy B sell: AAPL's 14-day RSI closes above 60
        if self.strategy_b_shares > 0:
            if aapl_rsi > 60:
                self.MarketOrder("AAPL", -self.strategy_b_shares)
                self.strategy_b_shares = 0

        # Evaluate buys
        # Strategy A buy: SPY crosses above 100-day SMA
        if self.strategy_a_shares == 0:
            if self.prices["SPY"][-2] <= spy_sma_yesterday and spy_price > spy_sma_today:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                buy_value = portfolio_value * 0.40
                shares_to_buy = int(buy_value / spy_price)
                if shares_to_buy > 0:
                    self.MarketOrder("SPY", shares_to_buy)
                    self.strategy_a_shares = shares_to_buy

        # Strategy B buy: AAPL red for 3+ consecutive days
        if self.strategy_b_shares == 0:
            if self.aapl_red_streak >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares_to_buy = int(20000 / aapl_price)
                    if shares_to_buy > 0:
                        self.MarketOrder("AAPL", shares_to_buy)
                        self.strategy_b_shares = shares_to_buy

        # Trim price history to save memory
        if len(self.prices["SPY"]) > 200:
            for ticker in self.tickers:
                self.prices[ticker] = self.prices[ticker][-200:]

    def CalculateRSI(self, closes, period):
        if len(closes) < period + 1:
            return 50

        recent_closes = closes[-(period+1):]

        gains = 0
        losses = 0

        for i in range(1, len(recent_closes)):
            change = recent_closes[i] - recent_closes[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))

        return rsi

